import {pressureContextChartSvg} from '../dist/pressureSupportChart.js';
/** Parses only SVG generated by the shared pure module; parser errors are rejected and no markup string is assigned to the live DOM. */
export function renderPressureContextChart(result){
 const doc=new DOMParser().parseFromString(pressureContextChartSvg(result),'image/svg+xml');
 if(doc.getElementsByTagName('parsererror').length||doc.documentElement.localName!=='svg')throw new Error('Generated context chart could not be parsed.');
 return document.importNode(doc.documentElement,true);
}
export {pressureContextChartSvg};
